import unittest

from solution import compose_node_config


class ComposeNodeConfigTests(unittest.TestCase):
    def test_recursive_merge_and_order(self):
        common = {
            "host": "shared",
            "network": {
                "timeout": 10,
                "headers": {"accept": "json", "agent": "common"},
            },
            "workers": 2,
        }
        overrides = {
            "api": {
                "network": {
                    "headers": {"agent": "api", "trace": "on"},
                    "retries": 3,
                },
                "workers": 8,
                "debug": True,
            }
        }
        result = compose_node_config(common, overrides, "api")
        self.assertEqual(
            result,
            {
                "host": "shared",
                "network": {
                    "timeout": 10,
                    "headers": {"accept": "json", "agent": "api", "trace": "on"},
                    "retries": 3,
                },
                "workers": 8,
                "debug": True,
            },
        )
        self.assertEqual(list(result), ["host", "network", "workers", "debug"])
        self.assertEqual(
            list(result["network"]), ["timeout", "headers", "retries"]
        )
        self.assertEqual(
            list(result["network"]["headers"]), ["accept", "agent", "trace"]
        )

    def test_unknown_role_uses_deep_copy_of_common(self):
        common = {"nested": {"items": [1, {"x": 2}]}}
        result = compose_node_config(common, {}, "unknown")
        self.assertEqual(result, common)
        self.assertIsNot(result, common)
        self.assertIsNot(result["nested"], common["nested"])
        self.assertIsNot(result["nested"]["items"], common["nested"]["items"])
        self.assertIsNot(result["nested"]["items"][1], common["nested"]["items"][1])

    def test_override_replaces_when_only_one_side_is_dictionary(self):
        common = {"a": {"nested": 1}, "b": 2}
        overrides = {"role": {"a": "replacement", "b": {"new": 3}}}
        self.assertEqual(
            compose_node_config(common, overrides, "role"),
            {"a": "replacement", "b": {"new": 3}},
        )

    def test_inputs_and_nested_values_are_not_mutated_or_aliased(self):
        common = {"settings": {"common_list": [1, 2]}}
        overrides = {
            "worker": {"settings": {"override_list": [{"enabled": True}]}}
        }
        result = compose_node_config(common, overrides, "worker")
        self.assertEqual(common, {"settings": {"common_list": [1, 2]}})
        self.assertEqual(
            overrides,
            {"worker": {"settings": {"override_list": [{"enabled": True}]}}},
        )

        common["settings"]["common_list"].append(3)
        overrides["worker"]["settings"]["override_list"][0]["enabled"] = False
        self.assertEqual(
            result,
            {
                "settings": {
                    "common_list": [1, 2],
                    "override_list": [{"enabled": True}],
                }
            },
        )

        result["settings"]["common_list"].append(99)
        result["settings"]["override_list"][0]["enabled"] = "changed"
        self.assertEqual(common["settings"]["common_list"], [1, 2, 3])
        self.assertFalse(
            overrides["worker"]["settings"]["override_list"][0]["enabled"]
        )

    def test_empty_configuration(self):
        self.assertEqual(compose_node_config({}, {}, "role"), {})

    def test_malformed_arguments(self):
        cases = [
            (None, {}, "role"),
            ([], {}, "role"),
            ({}, None, "role"),
            ({}, [], "role"),
            ({}, {}, ""),
            ({}, {}, None),
            ({}, {}, 1),
            ({}, {"": {}}, "role"),
            ({}, {1: {}}, "role"),
            ({}, {"role": []}, "role"),
            ({}, {"role": None}, "role"),
        ]
        for args in cases:
            with self.subTest(args=args):
                with self.assertRaises(ValueError):
                    compose_node_config(*args)


if __name__ == "__main__":
    unittest.main()

